mapper.select:
SELECT d.path, d.language, c.chunk_type, c.symbol_name, c.business_summary, c.source_snippet, COALESCE((c.metadata ->> 'startLine')::int, 0) AS start_line, COALESCE((c.metadata ->> 'endLine')::int, 0) AS end_line, (
(CASE WHEN c.symbol_name ILIKE '%' || #{kw} || '%' THEN 5 ELSE 0 END + CASE WHEN d.path ILIKE '%' || #{kw} || '%' THEN 2 ELSE 0 END + CASE WHEN c.source_snippet ILIKE '%' || #{kw} || '%' THEN 1 ELSE 0 END)
) AS score FROM ai_code_chunk c JOIN ai_code_document d ON d.id = c.document_id WHERE d.project_id = #{projectId} AND c.source_snippet IS NOT NULL AND (
c.symbol_name ILIKE '%' || #{kw} || '%' OR d.path ILIKE '%' || #{kw} || '%' OR c.source_snippet ILIKE '%' || #{kw} || '%'
) ORDER BY score DESC, length(c.source_snippet) ASC LIMIT #{limit}
